            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }

        /* Try to use a cached object. */
        used_cache = 0;
        cached = (j < LUA_CMD_OBJCACHE_SIZE) ? lua_args_cached_objects[j] : NULL;
        if (cached != NULL) {
            if (lua_args_cached_objects_len[j] >= obj_len) {
                s = cached->ptr;
                lua_argv[j] = cached;
                lua_args_cached_objects[j] = NULL;
                memcpy(s,obj_s,obj_len+1);
                sds_flags = s[-1];
