                    case SDS_TYPE_8:
                        SDS_HDR(8,s)->len = obj_len;
                        break;
                    case SDS_TYPE_16:
                        SDS_HDR(16,s)->len = obj_len;
                        break;
                    case SDS_TYPE_32:
                        SDS_HDR(32,s)->len = obj_len;
                        break;
                    case SDS_TYPE_64:
                        SDS_HDR(64,s)->len = obj_len;
                        break;
